from collections import namedtuple
from math import sqrt


Geometry = namedtuple("Geometry", "length cosine sine dofs")
Properties = namedtuple("Properties", "area inertia young yield_stress density expansion stiffness")
Loading = namedtuple("Loading", "external total temperature settlement")


def member_geometry(nodes, members, node_dofs):
    geometry = []
    for member in members:
        start, end = nodes[member.start], nodes[member.end]
        dx, dy = end.x - start.x, end.y - start.y
        length = sqrt(dx * dx + dy * dy)
        geometry.append(Geometry(length, dx / length, dy / length,
                                 node_dofs[member.start] + node_dofs[member.end]))
    return geometry


def member_properties(model, choices, geometry):
    result = []
    for member, choice, shape in zip(model.members, choices, geometry):
        section, material = model.sections[choice], model.materials[member.material]
        result.append(Properties(section.area, section.inertia, material.young, material.yield_stress,
                                 material.density, material.expansion, material.young * section.area / shape.length))
    return result


def member_weight(properties, geometry):
    return properties.density * 9.81 * properties.area * geometry.length / 1000000000


def member_stiffness(properties, geometry):
    stiffness, c, s = properties.stiffness, geometry.cosine, geometry.sine
    xx, xy, yy = stiffness * (c * c), stiffness * (c * s), stiffness * (s * s)
    return ((xx, xy, -xx, -xy), (xy, yy, -xy, -yy),
            (-xx, -xy, xx, xy), (-xy, -yy, xy, yy))


def assemble(geometry, properties, degrees, removed=None):
    matrix = [[0.0] * degrees for _ in range(degrees)]
    for number, (shape, member) in enumerate(zip(geometry, properties)):
        if number == removed:
            continue
        local = member_stiffness(member, shape)
        for row, global_row in enumerate(shape.dofs):
            for column, global_column in enumerate(shape.dofs):
                matrix[global_row][global_column] += local[row][column]
    return matrix


def load_vectors(case, geometry, properties, node_dofs, degrees, removed=None):
    external, thermal = [0.0] * degrees, [0.0] * degrees
    temperature, settlement = [0.0] * len(geometry), False
    for line in case.lines:
        if line[0] == "FORCE":
            _, node, horizontal, vertical = line
            x, y = node_dofs[node]
            external[x] += horizontal * 1000
            external[y] += vertical * 1000
        elif line[0] == "TEMPERATURE":
            _, number, change = line
            if number == removed:
                continue
            member, shape = properties[number], geometry[number]
            force = member.young * member.area * member.expansion * change
            temperature[number] = force
            direction = (-shape.cosine, -shape.sine, shape.cosine, shape.sine)
            for degree, coefficient in zip(shape.dofs, direction):
                thermal[degree] += force * coefficient
        elif line[0] == "SELFWEIGHT":
            for number, (member, shape) in enumerate(zip(properties, geometry)):
                if number != removed:
                    weight = member_weight(member, shape)
                    external[shape.dofs[1]] -= weight / 2
                    external[shape.dofs[3]] -= weight / 2
        else:
            settlement = True
    total = [first + second for first, second in zip(external, thermal)]
    return Loading(external, total, temperature, settlement)

from math import sqrt


PI = 3.141592653589793


def buckling(properties, geometry, inertia=None):
    inertia = properties.inertia if inertia is None else inertia
    return PI * PI * properties.young * inertia / (geometry.length * geometry.length)


def utilization(force, properties, geometry, section=None):
    area = properties.area if section is None else section.area
    inertia = properties.inertia if section is None else section.inertia
    return max(abs(force / area) / properties.yield_stress,
               max(0, -force) / buckling(properties, geometry, inertia))


def slenderness(properties, geometry, section=None):
    area = properties.area if section is None else section.area
    inertia = properties.inertia if section is None else section.inertia
    return geometry.length / sqrt(inertia / area)


def slenderness_limit(number, combinations, limits):
    return limits[0] if any(result.forces[number] < 0 for result in combinations) else limits[1]


def select_section(members, sections, properties, geometry, combinations, limits):
    for number, section in enumerate(sections):
        acceptable = True
        for member in members:
            if slenderness(properties[member], geometry[member], section) > limits[member]:
                acceptable = False
                break
            for result in combinations:
                if utilization(result.forces[member], properties[member], geometry[member], section) > 1:
                    acceptable = False
                    break
            if not acceptable:
                break
        if acceptable:
            return number
    return len(sections) - 1

import csv
from collections import namedtuple
from pathlib import Path


Node = namedtuple("Node", "identifier x y")
Member = namedtuple("Member", "identifier start end section material group")
Section = namedtuple("Section", "name area inertia")
Material = namedtuple("Material", "name young yield_stress density expansion")
Support = namedtuple("Support", "node fixed prescribed")
LoadCase = namedtuple("LoadCase", "name lines")
Combination = namedtuple("Combination", "name terms")
Model = namedtuple("Model", "nodes members sections materials supports cases combinations settings")


def csv_rows(name):
    with open("input/" + name + ".csv", encoding="ascii", newline="") as source:
        rows = csv.reader(source)
        next(rows)
        return list(rows)


def read_loads(node_index, member_index):
    cases, combinations = [], []
    for line in Path("input/loads.txt").read_text(encoding="ascii").splitlines():
        kind, *values = line.split()
        if kind == "LOADCASE":
            name, loads = values[0], []
        elif kind == "END":
            cases.append(LoadCase(name, loads))
        elif kind == "COMBINATION":
            terms = [(values[index], float(values[index + 1])) for index in range(1, len(values), 2)]
            combinations.append(Combination(values[0], terms))
        elif kind == "FORCE":
            loads.append((kind, node_index[int(values[0])], float(values[1]), float(values[2])))
        elif kind == "TEMPERATURE":
            loads.append((kind, member_index[int(values[0])], float(values[1])))
        else:
            loads.append((kind,))
    return cases, combinations


def read_settings(node_index, member_index):
    settings = {"influence": [], "drawing": []}
    for line in Path("input/params.txt").read_text(encoding="ascii").splitlines():
        kind, *values = line.split()
        if kind == "deck":
            settings[kind] = [node_index[int(value)] for value in values]
        elif kind == "influence":
            settings[kind].append(member_index[int(values[0])])
        elif kind == "vehicle":
            axles = [(int(values[index]), float(values[index + 1])) for index in range(1, len(values), 2)]
            settings[kind] = int(values[0]), axles
        elif kind == "rating":
            settings[kind] = values[0], float(values[1]), float(values[2])
        elif kind == "slenderness":
            settings[kind] = tuple(map(float, values))
        elif kind == "deflection":
            settings[kind] = values[0], int(values[1])
        elif kind == "vibration":
            settings[kind] = values[0], int(values[1]), int(values[2])
        elif kind == "removal":
            settings[kind] = values[0]
        elif kind == "drawing":
            settings[kind].append((values[0], *map(int, values[1:])))
        else:
            settings[kind] = tuple(map(int, values))
    return settings


def read_model():
    nodes = [Node(*map(int, row)) for row in csv_rows("nodes")]
    sections = [Section(row[0], float(row[1]), float(row[2])) for row in csv_rows("sections")]
    materials = [Material(row[0], *map(float, row[1:])) for row in csv_rows("materials")]
    node_index = {node.identifier: index for index, node in enumerate(nodes)}
    section_index = {section.name: index for index, section in enumerate(sections)}
    material_index = {material.name: index for index, material in enumerate(materials)}
    members = [Member(int(row[0]), node_index[int(row[1])], node_index[int(row[2])],
                      section_index[row[3]], material_index[row[4]], row[5]) for row in csv_rows("members")]
    member_index = {member.identifier: index for index, member in enumerate(members)}
    supports = [Support(node_index[int(row[0])], (int(row[1]), int(row[2])),
                        (float(row[3]), float(row[4]))) for row in csv_rows("supports")]
    cases, combinations = read_loads(node_index, member_index)
    settings = read_settings(node_index, member_index)
    return Model(nodes, members, sections, materials, supports, cases, combinations, settings)

from collections import namedtuple


Result = namedtuple("Result", "name displacement forces reactions external")


def axial_forces(geometry, properties, displacement, temperature, removed=None):
    forces = [0.0] * len(geometry)
    for number, (shape, member) in enumerate(zip(geometry, properties)):
        if number == removed:
            continue
        ix, iy, jx, jy = shape.dofs
        extension = ((displacement[jx] - displacement[ix]) * shape.cosine
                     + (displacement[jy] - displacement[iy]) * shape.sine)
        forces[number] = member.stiffness * extension - temperature[number]
    return forces


def reactions(matrix, displacement, force, restrained):
    result = [0.0] * len(force)
    for row in restrained:
        value = 0.0
        for column in range(len(force)):
            value += matrix[row][column] * displacement[column]
        result[row] = value - force[row]
    return result


def superpose(combination, results):
    first_name, first_factor = combination.terms[0]
    vectors = [[first_factor * value for value in vector] for vector in results[first_name][1:]]
    for name, factor in combination.terms[1:]:
        for target, source in zip(vectors, results[name][1:]):
            for index, value in enumerate(source):
                target[index] += factor * value
    return Result(combination.name, *vectors)


def equilibrium_residual(result, geometry):
    residual = [external + reaction for external, reaction in zip(result.external, result.reactions)]
    for shape, force in zip(geometry, result.forces):
        direction = (shape.cosine, shape.sine, -shape.cosine, -shape.sine)
        for degree, coefficient in zip(shape.dofs, direction):
            residual[degree] += force * coefficient
    return max(abs(value) for value in residual)

from math import sqrt


def cholesky(matrix, free):
    size = len(matrix)
    lower = [[0.0] * size for _ in range(size)]
    for row in range(size):
        for column in range(row + 1):
            value = matrix[row][column]
            for index in range(column):
                value -= lower[row][index] * lower[column][index]
            if column < row:
                lower[row][column] = value / lower[column][column]
            else:
                if value <= 0.000000001 * matrix[row][row]:
                    return None, free[row]
                lower[row][row] = sqrt(value)
    return lower, None


def solve(lower, right):
    size = len(right)
    intermediate, result = [0.0] * size, [0.0] * size
    for row in range(size):
        value = right[row]
        for column in range(row):
            value -= lower[row][column] * intermediate[column]
        intermediate[row] = value / lower[row][row]
    for row in range(size - 1, -1, -1):
        value = intermediate[row]
        for column in range(row + 1, size):
            value -= lower[column][row] * result[column]
        result[row] = value / lower[row][row]
    return result
